global.performance = { now: () => fakeNow };
function makeCanvas() {
  const imageData = { data: new Uint8ClampedArray(320 * 200 * 4), width: 320, height: 200 };
  return { width: 0, height: 0, style: {}, getContext: () => ({ createImageData: () => imageData, putImageData: () => {} }) };
}
const canvas = makeCanvas();
global.document = { getElementById: (id) => (id === 'raptor-canvas' ? canvas : { textContent: '', set textContent(v) { this._t = v; } }) };
global.window = global;
global.addEventListener = () => {};
global.requestAnimationFrame = (cb) => { setTimeout(() => { fakeNow += 16.67; cb(fakeNow); }, 0); };

// patch the SAME module instance main.js will use: make waves survivable so the
// wave-flow/complete path (the M5 contract) is exercised, not player death.
const eng = await import('../js/engine.js');
const orig = eng.Raptor.prototype.startWave;
eng.Raptor.prototype.startWave = function (wave) { orig.call(this, wave); this.godmode = true; };

await import('../js/main.js');
await new Promise((r) => setTimeout(r, 60));
const R = global.__raptor;
const waveLog = new Set();
const t0 = Date.now();
while (!R.sectorComplete && Date.now() - t0 < 30000) { waveLog.add(R.wave); await new Promise((r) => setTimeout(r, 40)); }
console.log('waves seen (1-based):', [...waveLog].join(','));
console.log('final: wave =', R.wave, 'sectorComplete =', R.sectorComplete, 'player.alive =', R.player.alive, 'ready =', R.ready);
console.log('elapsed ms:', Date.now() - t0);
process.exit(0);
EOF
