import { loadGLB } from '../js/glb.js';
import { Raptor } from '../js/engine.js';
const glb0 = await loadGLB('data/FILE0000.GLB');
const glb1 = await loadGLB('data/FILE0001.GLB');
const g = new Raptor(glb0, glb1);
g.init();
g.setAudio({ play: () => false });
g.godmode = true;              // isolate wave-flow; death path already proven
g.startWave(0);
let dir = 1, strafeT = 0;
const autoplay = () => {
  g.keys.fire = true;
  if (g.playerx < 10) dir = 1; else if (g.playerx > 260) dir = -1;
  if (++strafeT % 120 === 0) dir = -dir;
  g.keys.left = dir < 0; g.keys.right = dir > 0;
  g.keys.down = g.playery < 150; g.keys.up = g.playery > 180;
};
let wave = 0, between = 0, complete = false, frames = 0, lastWaveLen = -1;
while (!complete && frames < 300000) {
  frames++;
  if (between > 0) { between--; autoplay(); if (between === 0) { wave++; g.startWave(wave); } continue; }
  autoplay();
  g.frame();
  if (g.end_wave) { if (wave >= 8) { complete = true; g.sectorComplete = true; } else between = 60; }
  if (g.enemies.length !== lastWaveLen) { lastWaveLen = g.enemies.length; if (frames % 5000 === 0) console.log('step', frames, 'wave', wave, 'ships', g.enemies.length, 'score', g.score); }
}
console.log('complete:', complete, 'wave:', wave + 1, 'sectorComplete:', g.sectorComplete, 'frames:', frames, 'score', g.score);
EOF
