g.startWave(0);
let dir=1, st=0;
const autoplay=()=>{ g.keys.fire=true; if(g.playerx<10)dir=1; else if(g.playerx>260)dir=-1; if(++st%120===0)dir=-dir; g.keys.left=dir<0; g.keys.right=dir>0; g.keys.down=g.playery<150; g.keys.up=g.playery>180; };
let wave=0, between=0, complete=false, frames=0;
while (!complete && frames<300000) {
  frames++;
  if (between>0){ between--; autoplay(); if(between===0){wave++; g.startWave(wave);} continue; }
  autoplay(); g.frame();
  if (g.end_wave){ if(wave>=8){complete=true; g.sectorComplete=true;} else between=60; }
}
console.log('done', complete, wave+1);
" 2>&1 | head -30

