  if (wave > maxWaveSeen) maxWaveSeen = wave;
  if (g.end_wave) {
    if (wave >= 8) { complete = true; g.sectorComplete = true; }
    else between = 60;
  }
}
console.log('complete:', complete, 'maxWave(0-based):', maxWaveSeen, '1-based wave:', wave+1, 'frames:', frames, 'sectorComplete:', g.sectorComplete);
console.log('live __raptor equivalent — wave:', wave+1, 'sectorComplete:', g.sectorComplete);
" 2>&1

