import { loadGLB } from '../js/glb.js';
import { Raptor } from '../js/engine.js';

const glb0 = await loadGLB('data/FILE0000.GLB');
const glb1 = await loadGLB('data/FILE0001.GLB');

// Autoplay: hold fire, stay low, strafe to sweep the playfield horizontally.
// Air enemies dive from the top into the line of fire; ground enemies descend into
// the player's row and get shot. This clears waves the way the real game does.
function makeAutoplay() {
  let dir = 1, strafeT = 0;
  return (g) => {
    g.keys.fire = true;
    // strafe: reverse when near an edge or periodically
    if (g.playerx < 10) dir = 1;
    else if (g.playerx > 260) dir = -1;
    if (++strafeT % 90 === 0) dir = -dir;
    g.keys.left = dir < 0;
    g.keys.right = dir > 0;
    // keep in the lower third but sweep up a little so upward shots reach
    g.keys.down = g.playery < 150;
    g.keys.up = g.playery > 175;
  };
}

const g = new Raptor(glb0, glb1);
g.init();
g.setAudio({ play: () => false });
g.startWave(0);
const autoplay = makeAutoplay();
let wave = 0, between = 0, complete = false, frames = 0;
while (!complete && frames < 600000) {
  frames++;
  if (between > 0) { between--; autoplay(g); if (between === 0) { wave++; g.startWave(wave); } continue; }
  autoplay(g);
  g.frame();
  if (g.dead) { wave = 0; between = 0; frames = 0; g.startWave(0); continue; }
  if (g.end_wave) {
    if (wave >= 8) { complete = true; g.sectorComplete = true; }
    else between = 60;
  }
  if (frames % 20000 === 0) console.log('step', frames, 'wave', wave, 'energy', g.energy, 'score', g.score, 'ships', g.enemies.length);
}
console.log('complete:', complete, 'wave:', wave + 1, 'sectorComplete:', g.sectorComplete, 'frames:', frames, 'energy', g.energy, 'score', g.score);
EOF
