   {
      curfld = &csprite [ loop ];
      curlib = &slib [ csprite [ loop ].game ] [ curfld->slib ];
      curlib->item = GLB_GetItemID ( curlib->iname );

      switch ( curfld->level )
      {
         default:
            curfld->level = EB_NOT_USED;
            break;

         case E_SECRET_1:
            curfld->level = EB_SECRET_1;
