            curfld->level = EB_SECRET_3;
            break;

         case E_EASY_LEVEL:
            curfld->level = EB_EASY_LEVEL;
            break;

         case E_MED_LEVEL:
            curfld->level = EB_MED_LEVEL;
            break;

         case E_HARD_LEVEL:
            curfld->level = EB_HARD_LEVEL;
            break;
      }

      if ( curfld->level & cur_diff )
      {
         if ( curlib->item != EMPTY )
         {
            for ( i = 0; i < curlib->num_frames; i++ )
            {
